    'zoho_mapping_info' => 'वे फ़ील्ड चुनें जिन्हें आप अपने संपर्कों को फ़ेवियो इनवॉइसिंग और ज़ोहो के बीच समन्वयित रखने के लिए मैप करना चाहते हैं। बाईं ओर ज़ोहो फ़ील्ड और दाईं ओर संबंधित फ़ेवियो फ़ील्ड का चयन करें।',
    'zoho_mapping_owner_blocked' => ':field: यह फ़ील्ड ज़ोहो द्वारा प्रबंधित किया जाता है और इसके लिए ज़ोहो उपयोगकर्ता की आवश्यकता होती है। आपको इसमें किसी स्थानीय फ़ील्ड को मैप करने की आवश्यकता नहीं है; ज़ोहो इसे स्वचालित रूप से असाइन करेगा।',
    'zoho_mapping_lookup_blocked' => ':field: यह फ़ील्ड ज़ोहो में मौजूदा रिकॉर्ड से जुड़ा होना चाहिए। यहां स्थानीय फ़ील्ड का उपयोग नहीं किया जा सकता क्योंकि यह मौजूदा रिकॉर्ड से लिंक होने के बजाय डुप्लिकेट रिकॉर्ड बना सकता है।',
    'zoho_mapping_image_blocked' => ':field: इस फ़ील्ड के लिए ज़ोहो में अपलोड की गई छवि की आवश्यकता है। कोई स्थानीय फ़ील्ड वह प्रदान नहीं कर सकता, इसलिए इसे यहां मैप नहीं किया जा सकता।',
    'zoho_mapping_datetime_blocked' => ':field: यह फ़ील्ड ज़ोहो द्वारा प्रबंधित किया जाता है और स्वचालित रूप से अपडेट होता है। किसी स्थानीय फ़ील्ड को इससे मैप करने से कोई प्रभाव नहीं पड़ेगा.',
    'zoho_mapping_picklist_has_options' => ':field: ज़ोहो इस क्षेत्र के लिए विकल्पों की एक पूर्वनिर्धारित सूची प्रदान करता है। कृपया स्थानीय फ़ील्ड को मैप करने के बजाय उपलब्ध ज़ोहो विकल्पों में से एक का चयन करें।',
    'zoho_mapping_type_mismatch' => ':field: यह फ़ील्ड ज़ोहो में :zoho_type की अपेक्षा करता है, लेकिन \':local_field\' केवल :local_type रखता है। कृपया सही प्रकार का स्थानीय फ़ील्ड चुनें, अन्यथा इस मैपिंग का उपयोग करने पर ज़ोहो पूरे रिकॉर्ड को अस्वीकार कर देगा।',
