    'google_description' => 'Google reCAPTCHA इंटीग्रेशन सभी अप्रमाणित पृष्ठों पर reCAPTCHA सुविधा जोड़ता है, जो आपकी फ़ॉर्म्स को बॉट्स और स्वचालित सबमिशन से सुरक्षित रखता है, यह सुनिश्चित करता है कि केवल वास्तविक उपयोगकर्ता ही जानकारी सबमिट कर सकें।',
    'license_description' => 'Faveo लाइसेंस मैनेजर इंटीग्रेशन Faveo इनवॉइसिंग के भीतर सॉफ़्टवेयर लाइसेंस और अपडेट प्रबंधन की सुविधा जोड़ता है, जिससे प्लेटफ़ॉर्म के माध्यम से लाइसेंस का ट्रैकिंग, सक्रियण और अपडेटिंग आसान होता है।',
    'msg91_description' => 'MSG91.com सेवा का उपयोग OTP (वन-टाइम पासवर्ड) भेजने के लिए किया जाता है ताकि पंजीकरण के दौरान संपर्क के मोबाइल नंबर की पुष्टि की जा सके, यह संपर्क सत्यापन का एक सुरक्षित और भरोसेमंद तरीका है।',
    'mailchimp_description' => 'Mailchimp प्लगइन Faveo इनवॉइसिंग से सभी संपर्क डेटा को Mailchimp में पंजीकरण और प्रोफ़ाइल संपादन के दौरान स्वचालित रूप से भेजता है। साथ ही, खरीद डेटा को Mailchimp से मैप किया जा सकता है। एक समर्पित मैपिंग पेज उपयोगकर्ताओं को यह अनुकूलित करने की अनुमति देता है कि कौन सा डेटा दोनों प्लेटफ़ॉर्म के बीच सिंक होना चाहिए।',
    'terms_description' => 'जब "पंजीकरण पृष्ठ पर शर्तें दिखाएं" विकल्प सक्षम होता है, तो पंजीकरण पृष्ठ पर एक चेकबॉक्स प्रदर्शित होता है, जिसमें उपयोगकर्ताओं को पंजीकरण पूरा करने से पहले शर्तों और नियमों से सहमत होना आवश्यक होता है।',
    'pipedrive_description' => 'Pipedrive CRM प्लगइन Faveo इनवॉइसिंग से सभी संपर्क डेटा को पंजीकरण और प्रोफ़ाइल संपादन के दौरान स्वचालित रूप से Pipedrive CRM में भेजता है। एक समर्पित मैपिंग पेज उपयोगकर्ताओं को यह अनुकूलित करने की अनुमति देता है कि कौन से डेटा फ़ील्ड दोनों प्लेटफ़ॉर्म के बीच सिंक होने चाहिए।',
    'github_description' => 'GitHub इंटीग्रेशन GitHub रिपॉजिटरी से सीधे उत्पाद प्राप्त करने और डाउनलोड करने की सुविधा जोड़ता है, जिससे आपके GitHub प्रोजेक्ट्स से फाइलों को एक्सेस और प्रबंधित करना आसान हो जाता है।',
