    'map_is_paid_info' => 'एक Mailchimp रुचि श्रेणी का चयन करें जिसमें हाँ/सही और नहीं/गलत नामक दो रुचियाँ हों। प्रत्येक खरीदारी के बाद, ग्राहकों को तदनुसार टैग किया जाएगा।',
