    'no_interest_groups_found' => 'इस सूची के लिए कोई रुचि समूह नहीं मिला। पहले अपने Mailchimp खाते में रुचि श्रेणियां बनाएं।',
    'interest_group' => 'रुचि समूह',
    'map_is_paid_group' => 'मैप इज पेड ग्रुप',
    'map_is_paid_hint' => 'यह सेटिंग परिभाषित करती है कि उत्पाद शुल्क लिया गया है या मुफ़्त है। मेलचिम्प में ड्रॉपडाउन मानों के साथ एक समूह बनाएं जो या तो हाँ/नहीं या सत्य/गलत होना चाहिए। एक बार सहेजने के बाद, प्रत्येक उत्पाद की खरीद के बाद उसकी स्थिति आपके मेलचिम्प खाता समूह के अनुभाग में दिखाई देगी।',
    'pipedrive_user_verification_tooltip' => 'यदि उपयोगकर्ता को केवल सत्यापन पूरा करने के बाद पाइपड्राइव में जोड़ने की अनुमति है, तो इसे सक्षम करें।',
    'user_verification' => 'पाइपड्राइव में उपयोगकर्ता जोड़ने के लिए सत्यापन आवश्यक है',
    'pipedrive_config_info' => 'उन फ़ील्ड्स का चयन करें जिन्हें आप मैप करना चाहते हैं ताकि Faveo Invoicing और Pipedrive के बीच संपर्क, संगठन और सौदे सिंक में रहें। कुछ पाइपड्राइव फ़ील्ड्स में डिफ़ॉल्ट ड्रॉपडाउन विकल्प होते हैं, जिन्हें हम मैपिंग के दौरान दिखाते हैं। अन्य सभी फ़ील्ड्स के लिए, आप Faveo Invoicing फ़ील्ड्स देखेंगे।',
