    'gateway_desc_paypal' => 'PayPal का उपयोग करके दुनिया भर में भुगतान स्वीकार करें - 200 से अधिक देशों और कई मुद्राओं का समर्थन करने वाले सबसे भरोसेमंद ऑनलाइन भुगतान प्लेटफार्मों में से एक।',
    'gateway_desc_stripe' => 'स्ट्राइप के शक्तिशाली डेवलपर-अनुकूल भुगतान बुनियादी ढांचे के साथ वैश्विक स्तर पर कार्ड, वॉलेट और स्थानीय भुगतान विधियों को संसाधित करें।',
    'gateway_desc_razorpay' => 'भारत का अग्रणी भुगतान गेटवे जो निर्बाध चेकआउट अनुभव के साथ यूपीआई, कार्ड, नेट बैंकिंग, वॉलेट और ईएमआई का समर्थन करता है।',
    'gateway_desc_amazon' => 'ग्राहकों को तेज़, विश्वसनीय और परिचित चेकआउट अनुभव के लिए अपने अमेज़न खाते के क्रेडेंशियल्स का उपयोग करके भुगतान करने दें।',
    'gateway_desc_google' => 'Google Pay के साथ तेज़ और सुरक्षित चेकआउट सक्षम करें - Android, Chrome और वेब पर काम करता है।',
    'gateway_desc_apple' => 'Apple डिवाइस उपयोगकर्ताओं को Apple Pay के माध्यम से फेस आईडी, टच आईडी या पासकोड का उपयोग करके जल्दी और सुरक्षित रूप से भुगतान करने की अनुमति दें।',
    'gateway_desc_mollie' => 'एक लचीला यूरोपीय भुगतान गेटवे जो कार्ड, iDEAL, Bancontact, SEPA और कई अन्य स्थानीय तरीकों की पेशकश करता है।',
    'gateway_desc_paytm' => 'भारत का लोकप्रिय डिजिटल वॉलेट और पेमेंट गेटवे जो UPI, कार्ड, नेट बैंकिंग और Paytm वॉलेट को सपोर्ट करता है।',
    'gateway_desc_cashfree' => 'भुगतान, सदस्यता और त्वरित निपटान के समर्थन के साथ भारतीय व्यवसायों के लिए तेज़ और विश्वसनीय भुगतान गेटवे।',
    'gateway_desc_instamojo' => 'भारतीय एसएमबी के लिए सरल भुगतान गेटवे - शून्य सेटअप शुल्क के साथ लिंक, यूपीआई, कार्ड और वॉलेट के माध्यम से भुगतान स्वीकार करें।',
    'gateway_desc_flutterwave' => 'पैन-अफ्रीकी भुगतान प्लेटफ़ॉर्म व्यवसायों को पूरे अफ़्रीका और उसके बाहर भुगतान स्वीकार करने और भेजने में सक्षम बनाता है।',
    'gateway_desc_paystack' => 'कार्ड, बैंक ट्रांसफर, यूएसएसडी और मोबाइल मनी के समर्थन के साथ अफ्रीका का अग्रणी भुगतान गेटवे।',
    'gateway_desc_square' => 'व्यक्तिगत और ऑनलाइन भुगतान, इन्वेंट्री प्रबंधन और बिजनेस एनालिटिक्स के साथ एकीकृत वाणिज्य समाधान।',
    'gateway_desc_braintree' => 'एक पेपैल सेवा जो कार्ड, पेपाल, वेनमो और स्थानीय तरीकों के समर्थन के साथ लचीले भुगतान एकीकरण की पेशकश करती है।',
    'gateway_desc_authorize' => 'अमेरिका में सबसे स्थापित भुगतान गेटवे में से एक, जो सुरक्षित कार्ड प्रोसेसिंग और धोखाधड़ी का पता लगाने की सुविधा प्रदान करता है।',
    'gateway_desc_ccavenue' => 'कार्ड, नेट बैंकिंग, यूपीआई और वॉलेट सहित 200+ भुगतान विकल्पों के साथ भारत का सबसे बड़ा भुगतान गेटवे।',
    'gateway_desc_payu' => 'वैश्विक भुगतान प्लेटफ़ॉर्म 50+ बाज़ारों में मौजूद है, जो स्थानीय और अंतर्राष्ट्रीय भुगतान विधियों का समर्थन करता है।',
    'gateway_desc_worldpay' => 'भुगतान प्रसंस्करण में एक वैश्विक नेता - 146 देशों में कार्ड और वैकल्पिक भुगतान विधियां स्वीकार करता है।',
    'gateway_desc_klarna' => 'चेकआउट पर रूपांतरण बढ़ाने के लिए अभी खरीदें-बाद में भुगतान करें, किस्त योजनाएं और लचीले वित्तपोषण विकल्प प्रदान करें।',
    'gateway_desc_afterpay' => 'ग्राहकों को खरीदारी को 4 ब्याज-मुक्त किश्तों में विभाजित करने दें, जिससे औसत ऑर्डर मूल्य और रूपांतरण में वृद्धि होगी।',
    'webhook_secret' => 'वेबहुक सीक्रेट',
    'webhook_purpose_subscription_charged' => 'ऑटो-नवीनीकरण वास्तव में काम करने के लिए आवश्यक है - इसके बिना, रेज़रपे द्वारा ग्राहक से शुल्क लेने के बाद भी नवीनीकृत सदस्यता को बढ़ाया नहीं जाएगा।',
    'webhook_purpose_subscription_pending' => 'अपने पहले प्रयास में विफल होने पर नवीनीकरण शुल्क रिकॉर्ड करना आवश्यक है - इसके बिना, एक संघर्षपूर्ण ऑटो-नवीनीकरण तब तक अदृश्य है जब तक कि रेज़रपे अपने सभी पुनः प्रयास समाप्त नहीं कर लेता।',
    'webhook_purpose_subscription_halted' => 'विफल नवीनीकरण का पता लगाने के लिए आवश्यक - इसके बिना, ऐप को पता नहीं चलेगा कि आवर्ती शुल्क ने काम करना बंद कर दिया है, और ऑटो-नवीनीकरण चुपचाप टूटा हुआ रहता है।',
    'webhook_purpose_payment_captured' => 'चालान/ऑर्डर भुगतान की पुष्टि करना आवश्यक है - इसके बिना, ग्राहक सफलतापूर्वक भुगतान कर सकता है और चालान को अभी भी भुगतान के रूप में चिह्नित नहीं किया जाएगा।',
    'webhook_purpose_payment_failed' => 'विफल भुगतान का पता लगाने के लिए आवश्यक - इसके बिना, असफल भुगतान प्रयास पर किसी का ध्यान नहीं जाता है और ग्राहक को कभी भी पुनः प्रयास करने के लिए नहीं कहा जाता है।',
    'webhook_purpose_invoice_payment_succeeded' => 'वास्तव में काम करने के लिए ऑटो-नवीनीकरण के लिए आवश्यक - इसके बिना, स्ट्राइप द्वारा ग्राहक से शुल्क लेने के बाद भी नवीनीकृत सदस्यता को बढ़ाया नहीं जाएगा।',
    'webhook_purpose_invoice_payment_failed' => 'विफल नवीनीकरण का पता लगाने के लिए आवश्यक - इसके बिना, ऐप को पता नहीं चलेगा कि आवर्ती शुल्क ने काम करना बंद कर दिया है, और ऑटो-नवीनीकरण चुपचाप टूटा हुआ रहता है।',
    'webhook_purpose_customer_subscription_deleted' => 'ऑटो-नवीनीकरण स्थिति को सटीक रखने के लिए आवश्यक है - इसके बिना, स्ट्राइप में रद्द की गई सदस्यता अभी भी यहां सक्रिय दिखाई देती है।',
